func hooksFilePath(repoRoot string) string {
	return filepath.Join(repoRoot, ".grok", "hooks", hooksFileName)
}

func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	raw, err := parseHookInput(input)
	if err != nil {
		return nil, err
	}
	raw.HookEventName = grokEventName(hookName, raw.HookEventName, raw.HookEventNameCamel)
	normalizeRawHook(&raw, hookName)

	repoPath := raw.CWD
	if strings.TrimSpace(repoPath) == "" {
		repoPath = protocol.RepoRoot()
	}
	sessionRef := a.resolveSessionRef(raw.SessionID, repoPath)
	if err := a.writeSessionMarker(raw, sessionRef); err != nil {
		return nil, err
	}
	metadata := hookMetadata(raw)

	switch hookName {
	case HookNameSessionStart:
		return &protocol.EventJSON{
			Type:       1,
			SessionID:  raw.SessionID,
			SessionRef: sessionRef,
			Model:      raw.Model,
			Timestamp:  raw.Timestamp,
			Metadata:   metadata,
		}, nil
	case HookNameUserPromptSubmit:
		prompt := unwrapUserQuery(raw.Prompt)
		if prompt == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       2,
			SessionID:  raw.SessionID,
			SessionRef: sessionRef,
			Prompt:     prompt,
			Model:      raw.Model,
			Timestamp:  raw.Timestamp,
			Metadata:   metadata,
		}, nil
	case HookNameStop, HookNameStopCancelled:
		return &protocol.EventJSON{
			Type:            3,
			SessionID:       raw.SessionID,
			SessionRef:      sessionRef,
			Model:           raw.Model,
			Timestamp:       raw.Timestamp,
			ResponseMessage: raw.LastAssistantMessage,
			Metadata:        metadata,
		}, nil
	case HookNameStopFailure:
		return &protocol.EventJSON{
			Type:            3,
			SessionID:       raw.SessionID,
			SessionRef:      sessionRef,
			Model:           raw.Model,
			Timestamp:       raw.Timestamp,
			ResponseMessage: raw.ErrorDetails,
			Metadata:        metadata,
		}, nil
	case HookNameSessionEnd:
		return &protocol.EventJSON{
			Type:       5,
			SessionID:  raw.SessionID,
			SessionRef: sessionRef,
			Timestamp:  raw.Timestamp,
			Metadata:   metadata,
		}, nil
	case HookNamePreCompact:
		return &protocol.EventJSON{
			Type:       4,
			SessionID:  raw.SessionID,
			SessionRef: sessionRef,
			Timestamp:  raw.Timestamp,
			Metadata:   metadata,
		}, nil
	case HookNamePostCompact:
		return &protocol.EventJSON{
			Type:            4,
			SessionID:       raw.SessionID,
			SessionRef:      sessionRef,
			Timestamp:       raw.Timestamp,
			ResponseMessage: raw.CompactSummary,
			Type:       5,
			SessionID:  raw.SessionID,
			SessionRef: transcriptPath(raw.SessionID),
			Timestamp:  now,
		}, nil

	default:
		return nil, nil
	}
}

// writeSessionPayload persists the messages from a turn-end hook payload. The
// plugin sends messages in the "messages" field; older/blob payloads may carry
// them inside "session" instead. Stored as one-message-per-line JSONL so
// Entire's line-based transcript scoping lands on message boundaries.
func writeSessionPayload(sessionRef string, sessionRaw, messagesRaw json.RawMessage) error {
	if strings.TrimSpace(sessionRef) == "" {
		return errors.New("session_ref is required")
	}
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		return err
	}

	var messages []SessionMessage
	switch {
	case len(messagesRaw) > 0:
		if err := json.Unmarshal(messagesRaw, &messages); err != nil {
			return fmt.Errorf("parse messages payload: %w", err)
		}
	case len(sessionRaw) > 0:
		parsed, err := parseKiloExport(sessionRaw)
		if err != nil {
			return err
		}
		messages = parsed
	}

	// Never overwrite an existing transcript with an empty one. A failed
	// snapshot on the plugin side sends messages:[]; clobbering here would
	// destroy the last good transcript. Leave the existing file for
	// prepare-transcript / the next turn to refresh.
	if len(messages) == 0 {
		return nil
	}

	encoded, err := encodeMessagesJSONL(messages)
	if err != nil {
		return fmt.Errorf("encode session: %w", err)
	}
	return atomicWriteFile(sessionRef, encoded, 0o600)
}

