119	//
120	// This is the check the whole type exists for. The agent decides its own file
121	// layout via ResolveSessionFile — some nest, some append an extension — and the
122	// ID reaching it came from a hook payload. Converting the result back into a
123	// name relative to the store rejects an ID that walked out of the directory,
124	// which a plain filepath.Join would have produced silently.
125	func (s *SessionStore) SessionFile(agentSessionID string) (name, absPath string, err error) {
126		resolved := s.agent.ResolveSessionFile(s.dir, agentSessionID)
127		name, err = s.Name(resolved)
128		if err != nil {
129			return "", "", err
130		}
131		return name, resolved, nil
132	}
133	
134	// Name converts a path into a name inside the store, reporting
135	// ErrOutsideSessionStore for one that is not. A path already relative to the
136	// store is accepted as-is.
137	func (s *SessionStore) Name(p string) (string, error) {
138		if p == "" {
139			return "", fmt.Errorf("%w: empty path", ErrOutsideSessionStore)
140		}
141		// VolumeName alongside IsAbs, the pairing validation.ValidateSessionID and
142		// gitrepo's alternates checks already use. A Windows drive-relative path
143		// like "C:foo" contains no separator and IsAbs reports false, so it would
144		// otherwise be taken as a name inside the store — while filepath.Join drops
145		// the base directory when the appended element carries a volume. Sending it
146		// down the absolute branch makes filepath.Rel reject it across volumes,
147		// which is the answer this containment check exists to give. No-op on Unix,
148		// where VolumeName is always empty.
149		if !filepath.IsAbs(p) && filepath.VolumeName(p) == "" {
150			cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(p)))
151			if cleaned == "." || paths.IsRelativeTraversal(cleaned) {
152				return "", fmt.Errorf("%w: %s", ErrOutsideSessionStore, p)
153			}
154			return cleaned, nil
155		}
156		rel, err := filepath.Rel(s.dir, p)
157		if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
158			return "", fmt.Errorf("%w: %s is not inside %s", ErrOutsideSessionStore, p, s.dir)
159		}
160		return filepath.ToSlash(rel), nil
161	}
