163	// ReadFile reads name from the store.
164	func (s *SessionStore) ReadFile(name string) ([]byte, error) {
165		root, err := s.openRoot()
166		if err != nil {
167			return nil, err
168		}
169		defer root.Close()
170		return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
171	}
172	
173	// WriteFile writes name in the store, creating parent directories. Session
174	// layouts nest (Gemini keys by project hash, Pi by encoded repo path), so the
175	// parents are made here rather than at each call site.
176	func (s *SessionStore) WriteFile(name string, data []byte, perm os.FileMode) error {
177		root, err := s.openRootForWrite()
178		if err != nil {
179			return err
180		}
181		defer root.Close()
182		if dir := filepath.ToSlash(filepath.Dir(filepath.FromSlash(name))); dir != "." {
183			if err := osroot.MkdirAllNoSymlink(root, dir, 0o750); err != nil {
184				return fmt.Errorf("create session directory: %w", err)
185			}
186		}
187		if info, err := osroot.LstatNoSymlinks(root, name); err == nil && info.Mode()&os.ModeSymlink != 0 {
188			return fmt.Errorf("write session file: %w", osroot.ErrSymlinkedPath)
189		} else if err != nil && !os.IsNotExist(err) {
190			return fmt.Errorf("inspect session file: %w", err)
191		}
192		return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
193	}
