195	// Exists reports whether name is present in the store. Lstat, not Stat: a
196	// dangling symlink is still a file that exists and must not be overwritten
197	// silently (see the rewind restore path, which distinguishes the two).
198	func (s *SessionStore) Exists(name string) bool {
199		root, err := s.openRoot()
200		if err != nil {
201			return false
202		}
203		defer root.Close()
204		_, err = osroot.LstatNoSymlinks(root, name)
205		return err == nil
206	}
