208	// WriteSessionFile writes data to s.SessionRef through ag's own session store,
209	// creating parent directories.
210	//
211	// It exists because every agent's WriteSession was the same four lines —
212	// os.MkdirAll of the parent, then os.WriteFile of an absolute SessionRef — eight
213	// times over, each one taking the path on trust. Routing them through the store
214	// makes the containment one decision instead of eight, and the parent-directory
215	// create stops being something each agent has to remember.
216	//
217	// The store is anchored on s.RepoPath when it is set, which is the agent's real
218	// session directory for that repo. When it is not (callers that only carry a
219	// path, such as a restore driven from checkpoint metadata), the SessionRef's own
220	// directory anchors it: that contains nothing by itself, but it keeps the write
221	// on the same code path, and SessionRef there came from Entire's own resolution
222	// rather than from an agent payload.
223	func WriteSessionFile(ag SessionLocator, s *AgentSession, data []byte, perm os.FileMode) error {
224		if s == nil {
225			return errors.New("session is nil")
226		}
227		if s.SessionRef == "" {
228			return errors.New("session reference (transcript path) is required")
229		}
230	
231		store, err := sessionStoreForWrite(ag, s)
232		if err != nil {
233			return err
234		}
235		name, err := store.Name(s.SessionRef)
236		if err != nil {
237			return fmt.Errorf("write session: %w", err)
238		}
239		if err := store.WriteFile(name, data, perm); err != nil {
240			return fmt.Errorf("failed to write transcript: %w", err)
241		}
242		return nil
243	}
