245	// sessionStoreForWrite resolves the store a session write lands in.
246	//
247	// With a RepoPath, that is the agent's session directory for it, and a
248	// SessionRef outside that directory is an ERROR rather than a reason to anchor
249	// somewhere else. It used to fall through to SessionRef's own parent, which made
250	// the containment check its own off switch: the one input that fails it was the
251	// one input that disabled it. The comment justifying that said some agents
252	// resolve a restored session to a sibling directory — they do not.
253	// RestoredSessionPathResolver's only implementation (Codex) returns
254	// <sessionDir>/YYYY/MM/DD/rollout-*.jsonl, which nests INSIDE the store, so the
255	// branch was unreachable as well as unsound.
256	//
257	// Without a RepoPath the SessionRef's own directory is the only candidate there
258	// is. That anchor contains nothing by itself, and it is kept because the
259	// alternative is refusing to write at all; what makes it acceptable is that
260	// SessionRef there came from Entire's own resolution rather than from an agent
261	// payload.
262	func sessionStoreForWrite(ag SessionLocator, s *AgentSession) (*SessionStore, error) {
263		if s.RepoPath == "" {
264			return OpenSessionStoreAt(ag, filepath.Dir(s.SessionRef))
265		}
266	
267		store, err := OpenSessionStore(ag, s.RepoPath)
268		if err != nil {
269			return nil, err
270		}
271		if _, nameErr := store.Name(s.SessionRef); nameErr != nil {
272			return nil, fmt.Errorf("%w: %s is not inside %s's session directory %s",
273				ErrOutsideSessionStore, s.SessionRef, ag.Name(), store.Dir())
274		}
275		return store, nil
276	}
