    12		"github.com/entireio/cli/cmd/entire/cli/paths"
    13	)
    14	
    15	// SessionStore is one agent's own session directory, held as an *os.Root.
    16	//
    17	// Every agent keeps its transcripts somewhere Entire does not own —
    18	// ~/.claude/projects/<hash>/, ~/.codex/sessions/, Cursor's SQLite store,
    19	// ~/.pi/agent/sessions/<encoded-repo>/, a temp dir for OpenCode — and Entire
    20	// reads and writes into all of them. The session ID that selects a file inside
    21	// one comes from an agent hook payload, so this is where an untrusted name
    22	// becomes a path, and a store gives each agent one handle to resolve it through.
    23	//
    24	// It deliberately does NOT try to contain the agent's own writes: the agent is a
    25	// separate process writing its own store. What it contains is Entire's reads and
    26	// writes, which is the half Entire is responsible for.
    27	type SessionStore struct {
    28		agent SessionLocator
    29		dir   string
    30	}
    31	
    32	// SessionLocator is the slice of Agent a session store needs: where the agent
    33	// keeps sessions for a repo, and how it names a session's file inside that
    34	// directory. Narrow on purpose — a store has no business with transcripts,
    35	// chunking, or hooks, and depending on three methods instead of thirty is what
    36	// lets a test supply one without implementing the whole agent contract.
    37	type SessionLocator interface {
    38		Name() types.AgentName
    39		GetSessionDir(repoPath string) (string, error)
    40		ResolveSessionFile(sessionDir, agentSessionID string) string
    41	}
    42	
    43	// ErrOutsideSessionStore reports a session file that does not lie inside the
    44	// agent's session directory. Callers match it with errors.Is.
    45	var ErrOutsideSessionStore = errors.New("path is outside the agent's session directory")
    46	
    47	// OpenSessionStore returns ag's session store for repoPath.
    48	//
    49	// The directory need NOT exist yet: resolving a session file is path arithmetic
    50	// plus a containment check, and callers legitimately ask where a transcript
    51	// *would* live before anything has created the directory. Only the I/O methods
    52	// need the directory, and they open a root at that point and close it again —
    53	// see openRoot for why a store is not one of the memoized anchors.
    54	func OpenSessionStore(ag SessionLocator, repoPath string) (*SessionStore, error) {
    55		if ag == nil {
    56			return nil, errors.New("agent is required to open a session store")
    57		}
    58		dir, err := ag.GetSessionDir(repoPath)
    59		if err != nil {
    60			return nil, fmt.Errorf("resolve %s session directory: %w", ag.Name(), err)
    61		}
    62		return OpenSessionStoreAt(ag, dir)
    63	}
    64	
    65	// OpenSessionStoreAt is OpenSessionStore for a session directory the caller
    66	// already resolved — the cross-project fallbacks that scan sibling directories,
    67	// and agentimport, which is handed one.
    68	func OpenSessionStoreAt(ag SessionLocator, dir string) (*SessionStore, error) {
    69		if dir == "" {
    70			return nil, errors.New("session directory is required")
    71		}
    72		abs, err := filepath.Abs(dir)
    73		if err != nil {
    74			return nil, fmt.Errorf("resolve %s: %w", dir, err)
    75		}
    76		return &SessionStore{agent: ag, dir: abs}, nil
    77	}
    78	
    79	// Dir returns the store's absolute directory. It is for messages and for the
    80	// paths Entire hands to other processes (an agent's own resume command, a
    81	// transcript path recorded as a checkpoint's SessionRef); it is not an
    82	// invitation to do I/O on the result.
    83	func (s *SessionStore) Dir() string { return s.dir }
    84	
    85	// openRoot returns an *os.Root over the store directory. The CALLER closes it.
    86	//
    87	// Deliberately not osroot.Shared. That registry is for the handful of long-lived
    88	// anchors a process holds — .entire, the git common dir, the worktree — and it
    89	// never evicts, by design. A session store is not one of them: transcript
    90	// fallback search (searchTranscriptInProjectDirs) opens a store for EVERY
    91	// candidate directory it walks under ~/.claude/projects, and memoizing those
    92	// retained one directory fd per candidate for the life of the process. Measured
    93	// at exactly one fd per directory probed, against zero for the os.Stat this
    94	// replaced; a few hundred project directories is enough to reach the usual 1024
    95	// RLIMIT_NOFILE, at which point os.OpenRoot starts failing for every OTHER
    96	// anchor too, since they all come from the same registry.
    97	//
    98	// The cost of not sharing is one openat per store operation, against reading a
    99	// transcript that is routinely megabytes.
   100	//
   101	// A directory that does not exist is reported unwrapped so callers can classify
   102	// it with os.IsNotExist.
   103	func (s *SessionStore) openRoot() (*os.Root, error) {
   104		return os.OpenRoot(s.dir) //nolint:wrapcheck // see doc comment
   105	}
   106	
   107	// openRootForWrite is openRoot with the store directory created first. The
   108	// directory is the root itself, so it cannot be created through it — this is the
   109	// one place that reaches it from the outside. The caller closes the result.
   110	func (s *SessionStore) openRootForWrite() (*os.Root, error) {
   111		if err := os.MkdirAll(s.dir, 0o750); err != nil {
   112			return nil, fmt.Errorf("create session directory: %w", err)
   113		}
   114		return s.openRoot()
   115	}
