   117	// SessionFile resolves agentSessionID to a name inside the store, and to the
   118	// absolute path of the same file.
   119	//
   120	// This is the check the whole type exists for. The agent decides its own file
   121	// layout via ResolveSessionFile — some nest, some append an extension — and the
   122	// ID reaching it came from a hook payload. Converting the result back into a
   123	// name relative to the store rejects an ID that walked out of the directory,
   124	// which a plain filepath.Join would have produced silently.
   125	func (s *SessionStore) SessionFile(agentSessionID string) (name, absPath string, err error) {
   126		resolved := s.agent.ResolveSessionFile(s.dir, agentSessionID)
   127		name, err = s.Name(resolved)
   128		if err != nil {
   129			return "", "", err
   130		}
   131		return name, resolved, nil
   132	}
   133	
   134	// Name converts a path into a name inside the store, reporting
   135	// ErrOutsideSessionStore for one that is not. A path already relative to the
   136	// store is accepted as-is.
   137	func (s *SessionStore) Name(p string) (string, error) {
   138		if p == "" {
   139			return "", fmt.Errorf("%w: empty path", ErrOutsideSessionStore)
   140		}
   141		// VolumeName alongside IsAbs, the pairing validation.ValidateSessionID and
   142		// gitrepo's alternates checks already use. A Windows drive-relative path
   143		// like "C:foo" contains no separator and IsAbs reports false, so it would
   144		// otherwise be taken as a name inside the store — while filepath.Join drops
   145		// the base directory when the appended element carries a volume. Sending it
   146		// down the absolute branch makes filepath.Rel reject it across volumes,
   147		// which is the answer this containment check exists to give. No-op on Unix,
   148		// where VolumeName is always empty.
   149		if !filepath.IsAbs(p) && filepath.VolumeName(p) == "" {
   150			cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(p)))
   151			if cleaned == "." || paths.IsRelativeTraversal(cleaned) {
   152				return "", fmt.Errorf("%w: %s", ErrOutsideSessionStore, p)
   153			}
   154			return cleaned, nil
   155		}
   156		rel, err := filepath.Rel(s.dir, p)
   157		if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
   158			return "", fmt.Errorf("%w: %s is not inside %s", ErrOutsideSessionStore, p, s.dir)
   159		}
   160		return filepath.ToSlash(rel), nil
   161	}
   162	
   163	// ReadFile reads name from the store.
   164	func (s *SessionStore) ReadFile(name string) ([]byte, error) {
   165		root, err := s.openRoot()
   166		if err != nil {
   167			return nil, err
   168		}
   169		defer root.Close()
   170		return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
   171	}
   172	
   173	// WriteFile writes name in the store, creating parent directories. Session
   174	// layouts nest (Gemini keys by project hash, Pi by encoded repo path), so the
   175	// parents are made here rather than at each call site.
   176	func (s *SessionStore) WriteFile(name string, data []byte, perm os.FileMode) error {
   177		root, err := s.openRootForWrite()
   178		if err != nil {
   179			return err
   180		}
   181		defer root.Close()
   182		if dir := filepath.ToSlash(filepath.Dir(filepath.FromSlash(name))); dir != "." {
   183			if err := osroot.MkdirAllNoSymlink(root, dir, 0o750); err != nil {
   184				return fmt.Errorf("create session directory: %w", err)
   185			}
   186		}
   187		if info, err := osroot.LstatNoSymlinks(root, name); err == nil && info.Mode()&os.ModeSymlink != 0 {
   188			return fmt.Errorf("write session file: %w", osroot.ErrSymlinkedPath)
   189		} else if err != nil && !os.IsNotExist(err) {
   190			return fmt.Errorf("inspect session file: %w", err)
   191		}
   192		return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
   193	}
   194	
   195	// Exists reports whether name is present in the store. Lstat, not Stat: a
   196	// dangling symlink is still a file that exists and must not be overwritten
   197	// silently (see the rewind restore path, which distinguishes the two).
   198	func (s *SessionStore) Exists(name string) bool {
   199		root, err := s.openRoot()
   200		if err != nil {
   201			return false
   202		}
   203		defer root.Close()
   204		_, err = osroot.LstatNoSymlinks(root, name)
   205		return err == nil
   206	}
   207	
   208	// IsDir reports whether name is a real directory in the store. Symlinks in the
   209	// path are rejected by LstatNoSymlinks rather than followed.
   210	func (s *SessionStore) IsDir(name string) bool {
   211		root, err := s.openRoot()
   212		if err != nil {
   213			return false
   214		}
   215		defer root.Close()
   216		info, err := osroot.LstatNoSymlinks(root, name)
   217		return err == nil && info.IsDir()
   218	}
   219	
   220	// WriteSessionFile writes data to s.SessionRef through ag's own session store,
   221	// creating parent directories.
   222	//
   223	// It exists because every agent's WriteSession was the same four lines —
   224	// os.MkdirAll of the parent, then os.WriteFile of an absolute SessionRef — eight
   225	// times over, each one taking the path on trust. Routing them through the store
   226	// makes the containment one decision instead of eight, and the parent-directory
   227	// create stops being something each agent has to remember.
   228	//
   229	// The store is anchored on s.RepoPath when it is set, which is the agent's real
   230	// session directory for that repo. When it is not (callers that only carry a
   231	// path, such as a restore driven from checkpoint metadata), the SessionRef's own
   232	// directory anchors it: that contains nothing by itself, but it keeps the write
   233	// on the same code path, and SessionRef there came from Entire's own resolution
   234	// rather than from an agent payload.
   235	func WriteSessionFile(ag SessionLocator, s *AgentSession, data []byte, perm os.FileMode) error {
   236		if s == nil {
   237			return errors.New("session is nil")
   238		}
   239		if s.SessionRef == "" {
   240			return errors.New("session reference (transcript path) is required")
   241		}
   242	
   243		store, err := sessionStoreForWrite(ag, s)
   244		if err != nil {
   245			return err
   246		}
   247		name, err := store.Name(s.SessionRef)
   248		if err != nil {
   249			return fmt.Errorf("write session: %w", err)
   250		}
   251		if err := store.WriteFile(name, data, perm); err != nil {
   252			return fmt.Errorf("failed to write transcript: %w", err)
   253		}
   254		return nil
   255	}
   256	
   257	// sessionStoreForWrite resolves the store a session write lands in.
   258	//
   259	// With a RepoPath, that is the agent's session directory for it, and a
   260	// SessionRef outside that directory is an ERROR rather than a reason to anchor
   261	// somewhere else. It used to fall through to SessionRef's own parent, which made
   262	// the containment check its own off switch: the one input that fails it was the
   263	// one input that disabled it. The comment justifying that said some agents
   264	// resolve a restored session to a sibling directory — they do not.
   265	// RestoredSessionPathResolver's only implementation (Codex) returns
   266	// <sessionDir>/YYYY/MM/DD/rollout-*.jsonl, which nests INSIDE the store, so the
   267	// branch was unreachable as well as unsound.
   268	//
   269	// Without a RepoPath the SessionRef's own directory is the only candidate there
   270	// is. That anchor contains nothing by itself, and it is kept because the
   271	// alternative is refusing to write at all; what makes it acceptable is that
   272	// SessionRef there came from Entire's own resolution rather than from an agent
   273	// payload.
   274	func sessionStoreForWrite(ag SessionLocator, s *AgentSession) (*SessionStore, error) {
   275		if s.RepoPath == "" {
   276			return OpenSessionStoreAt(ag, filepath.Dir(s.SessionRef))
   277		}
   278	
   279		store, err := OpenSessionStore(ag, s.RepoPath)
   280		if err != nil {
   281			return nil, err
   282		}
   283		if _, nameErr := store.Name(s.SessionRef); nameErr != nil {
   284			return nil, fmt.Errorf("%w: %s is not inside %s's session directory %s",
   285				ErrOutsideSessionStore, s.SessionRef, ag.Name(), store.Dir())
   286		}
   287		return store, nil
   288	}

