     2	// It abstracts agent-specific behavior (hooks, log parsing, session storage) so that
     3	// the same Strategy implementations can work with any coding agent.
     4	package agent
     5	
     6	import (
     7		"context"
     8		"io"
     9		"os/exec"
    10		"time"
    11	
    12		"github.com/entireio/cli/cmd/entire/cli/agent/types"
    13	)
    14	
    15	// Agent defines the interface for interacting with a coding agent.
    16	// Each agent implementation (Claude Code, Cursor, Aider, etc.) converts its
    17	// native format to the normalized types defined in this package.
    18	//
    19	// The interface is organized into three groups:
    20	//   - Identity (5 methods): Name, Type, Description, DetectPresence, ProtectedDirs
    21	//   - Transcript Storage (3 methods): ReadTranscript, ChunkTranscript, ReassembleTranscript
    22	//   - Legacy (6 methods): Will be moved to optional interfaces or removed in a future phase
    23	type Agent interface {
    24		// --- Identity ---
    25	
    26		// Name returns the agent registry key (e.g., "claude-code", "gemini")
    27		Name() types.AgentName
    28	
    29		// Type returns the agent type identifier (e.g., "Claude Code", "Gemini CLI")
    30		// This is stored in metadata and trailers.
    31		Type() types.AgentType
    32	
    33		// Description returns a human-readable description for UI
    34		Description() string
    35	
    36		// IsPreview returns whether the agent integration is in preview or stable
    37		IsPreview() bool
    38	
    39		// DetectPresence checks if this agent is configured in the repository
    40		DetectPresence(ctx context.Context) (bool, error)
    41	
    42		// ProtectedDirs returns repo-root-relative directories that Entire must never
    43		// record as session changes or capture into a checkpoint.
    44		// Examples: [".claude"] for Claude, [".gemini"] for Gemini.
    45		ProtectedDirs() []string
    46	
    47		// --- Transcript Storage ---
    48	
    49		// ReadTranscript reads the raw transcript bytes for a session.
    50		ReadTranscript(sessionRef string) ([]byte, error)
    51	
    52		// ChunkTranscript splits a transcript into chunks if it exceeds maxSize.
    53		// Returns a slice of chunks. If the transcript fits in one chunk, returns single-element slice.
    54		// The chunking is format-aware: JSONL splits at line boundaries, JSON splits message arrays.
    55		ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error)
    56	
    57		// ReassembleTranscript combines chunks back into a single transcript.
    58		// Handles format-specific reassembly (JSONL concatenation, JSON message merging).
    59		ReassembleTranscript(chunks [][]byte) ([]byte, error)
    60	
    61		// --- Legacy methods (will move to optional interfaces in Phase 4) ---
    62	
    63		// GetSessionID extracts session ID from hook input.
    64		GetSessionID(input *HookInput) string
    65	
    66		// GetSessionDir returns where agent stores session data for this repo.
    67		GetSessionDir(repoPath string) (string, error)
    68	
    69		// ResolveSessionFile returns the path to the session transcript file.
    70		//
    71		// SECURITY CONTRACT: agentSessionID is used to build a filesystem path and
    72		// some implementations use it as a directory component or (Codex/Pi) return
    73		// it verbatim when absolute. Callers that source agentSessionID from
    74		// untrusted data (e.g. checkpoint metadata on the shared
    75		// entire/checkpoints/v1 branch, hook input) MUST validate it with
    76		// validation.ValidateSessionID first. The resume/log-restore paths do
    77		// this at their choke points (transcript.resolveTranscriptPath and
    78		// strategy.RestoreLogsOnly); do not call this with unvalidated input.
    79		ResolveSessionFile(sessionDir, agentSessionID string) string
    80	
    81		// ReadSession reads session data from agent's storage.
    82		ReadSession(input *HookInput) (*AgentSession, error)
    83	
    84		// WriteSession writes session data for resumption.
    85		WriteSession(ctx context.Context, session *AgentSession) error
    86	
    87		// FormatResumeCommand returns command to resume a session.
    88		FormatResumeCommand(sessionID string) string
    89	}
    90	
    91	// HookSupport is implemented by agents with lifecycle hooks.
    92	// This optional interface allows agents like Claude Code and Cursor to
    93	// install and manage hooks that notify Entire of agent events.
    94	//
    95	// The interface is organized into two groups:
    96	//   - Hook Mapping (2 methods): HookNames, ParseHookEvent
    97	//   - Hook Management (3 methods): InstallHooks, UninstallHooks, AreHooksInstalled
    98	type HookSupport interface {
    99		Agent
   100	
   101		// HookNames returns the hook verbs this agent supports.
   102		// These become subcommands under `entire hooks <agent>`.
   103		// e.g., ["stop", "user-prompt-submit", "session-start", "session-end"]
   104		HookNames() []string
   105	
   106		// ParseHookEvent translates an agent-native hook into a normalized lifecycle Event.
   107		// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
   108		// This is the core contribution surface for new agent implementations.
   109		ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*Event, error)
   110	
   111		// InstallHooks installs agent-specific hooks.
   112		// If force is true, removes existing Entire hooks before installing.
   113		// Returns the number of hooks installed.
   114		//
   115		// Installed hook commands must always name the "entire" binary, never a
   116		// path derived from repository content. Implementations recognize the
   117		// legacy local-dev command shapes (see LegacyLocalDevHookScript) only so
   118		// they can replace them.
   119		InstallHooks(ctx context.Context, force bool) (int, error)
   120	
   121		// UninstallHooks removes installed hooks
   122		UninstallHooks(ctx context.Context) error
   123	
   124		// AreHooksInstalled reports whether hooks are currently installed, and
   125		// returns an error when the agent could not find out.
   126		//
   127		// The two are different answers and callers may act on the difference: "no
   128		// hooks" means there is nothing to remove, while an error means the state is
   129		// unknown and hooks may well be installed. Built-in agents read a local
   130		// config file, where absent means absent, so they report no error. An
   131		// external agent answers over a subprocess that can crash, time out, or
   132		// print junk, and reports that as an error rather than as "no hooks".
   133		AreHooksInstalled(ctx context.Context) (bool, error)
   134	}
   135	
   136	// HookConfigState describes how an agent's installed Entire hook config
   137	// compares to what InstallHooks would write today.
   138	type HookConfigState int
   139	
   140	const (
   141		// HooksAbsent means Entire hooks are not installed for this agent here.
   142		HooksAbsent HookConfigState = iota
   143		// HooksCurrent means the installed hooks match what would be written today.
   144		HooksCurrent
   145		// HooksOutdated means Entire hooks are installed but stale — an older CLI
   146		// wrote a config that no longer matches the current one. Fix:
   147		// `entire enable --force`.
   148		HooksOutdated
   149	)
   150	
   151	// HookFreshness is implemented by hook-supporting agents that can report
   152	// whether their installed config has drifted from the current one.
   153	//
   154	// AreHooksInstalled answers "is Entire wired up here at all?" — for agents
   155	// whose hook config is a generated file checked into the repo, that stays true
   156	// forever even after the generated content goes stale, because the file is
