   161	//
   162	// Implementations must be read-only: they are diagnostics and must never
   163	// modify the agent's config.
   164	type HookFreshness interface {
   165		Agent
   166	
   167		// CheckHookConfig reports whether this agent's Entire hook config is
   168		// absent, current, or outdated in the current repo.
   169		CheckHookConfig(ctx context.Context) HookConfigState
   170	}
   171	
   172	// EffectiveHookDiagnostics marks agents whose effective hook state is reported
   173	// by an agent-owned diagnostic surface rather than generic freshness output.
   174	type EffectiveHookDiagnostics interface {
   175		Agent
   176		OwnsEffectiveHookDiagnostics()
   177	}
