    cmd: "rg -n 'ValidateSessionID|\\.\\. |trailing|reserved' cmd/entire/cli/validation/validators_test.go cmd/entire/cli/resume_test.go cmd/entire/cli/strategy --glob '*_test.go'",
    workdir: "/tmp/external-agent-cli-current.n2thgv/cli",
    yield_time_ms: 10000,
    max_output_tokens: 6000
  }),
  tools.exec_command({
    cmd: "rg -n 'func \\(.*WriteSession|WriteSessionFile' cmd/entire/cli/agent/external --glob '*.go'\nrg -n 'WriteSessionFile\\(' cmd/entire/cli/agent --glob '*.go' | sort",
    workdir: "/tmp/external-agent-cli-current.n2thgv/cli",
    yield_time_ms: 10000,
    max_output_tokens: 6000
  })
]);
for (const x of r) {
