234	func (e *Agent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
235		const maxParseHookBytes = 10 * 1024 * 1024 // 10 MB
236		// Stream a single (size-bounded) JSON value rather than io.ReadAll, so the
237		// hook never blocks waiting for stdin EOF that some agents don't send on
238		// Windows/Git Bash (issue #1398). The external "parse-hook" contract receives
239		// the host's hook payload — which is JSON — and we forward its raw bytes
240		// verbatim to the subprocess, so a plain byte copy is preserved.
241		raw, err := agent.ReadHookInputRawLimited(stdin, maxParseHookBytes)
242		if err != nil {
243			return nil, fmt.Errorf("parse-hook: read stdin: %w", err)
244		}
245		stdout, err := e.run(ctx, raw, "parse-hook", "--hook", hookName)
246		if err != nil {
247			return nil, fmt.Errorf("parse-hook: %w", err)
248		}
249		// null means no lifecycle significance
250		if bytes.Equal(bytes.TrimSpace(stdout), []byte("null")) {
251			return nil, nil //nolint:nilnil // protocol contract: null = no event
252		}
253		var event eventJSON
254		if err := json.Unmarshal(stdout, &event); err != nil {
255			return nil, fmt.Errorf("parse-hook: invalid JSON: %w", err)
256		}
257		return event.toEvent()
258	}
