 50	}
 51	
 52	// turnEndRaw is the payload for turn-end. Plugin writes the full session JSON
 53	// to session_ref before invoking; the Go binary verifies the file landed and
 54	// emits a TurnEnd event with the model captured at session.status time.
 55	type turnEndRaw struct {
 56		SessionID string          `json:"session_id"`
 57		Model     string          `json:"model"`
 58		Session   json.RawMessage `json:"session,omitempty"`
 59		Messages  json.RawMessage `json:"messages,omitempty"`
 60	}
 61	
 62	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
 63		if len(input) == 0 {
 64			return nil, nil
 65		}
 66	
 67		now := time.Now().UTC().Format(time.RFC3339)
 68	
 69		switch hookName {
 70		case HookNameSessionStart:
 71			var raw sessionInfoRaw
 72			if err := json.Unmarshal(input, &raw); err != nil {
 73				return nil, fmt.Errorf("parse session-start payload: %w", err)
 74			}
 75			if raw.SessionID == "" {
 76				return nil, nil
 77			}
 78			return &protocol.EventJSON{
 79				Type:       1,
 80				SessionID:  raw.SessionID,
 81				SessionRef: transcriptPath(raw.SessionID),
 82				Timestamp:  now,
 83			}, nil
 84	
 85		case HookNameTurnStart:
 86			var raw turnStartRaw
 87			if err := json.Unmarshal(input, &raw); err != nil {
 88				return nil, fmt.Errorf("parse turn-start payload: %w", err)
 89			}
 90			if raw.SessionID == "" {
 91				return nil, nil
 92			}
 93			return &protocol.EventJSON{
 94				Type:       2,
 95				SessionID:  raw.SessionID,
 96				SessionRef: transcriptPath(raw.SessionID),
 97				Prompt:     raw.Prompt,
 98				Model:      raw.Model,
 99				Timestamp:  now,
100			}, nil
101	
102		case HookNameTurnEnd:
103			var raw turnEndRaw
104			if err := json.Unmarshal(input, &raw); err != nil {
105				return nil, fmt.Errorf("parse turn-end payload: %w", err)
106			}
107			if raw.SessionID == "" {
108				return nil, nil
109			}
110			sessionRef := transcriptPath(raw.SessionID)
111			// Plugin may bundle the session snapshot in the payload (for instances
112			// where the plugin can't write to disk itself). Persist it to session_ref
113			// so downstream transcript operations see a populated file.
114			if len(raw.Session) > 0 || len(raw.Messages) > 0 {
115				if err := writeSessionPayload(sessionRef, raw.Session, raw.Messages); err != nil {
116					return nil, fmt.Errorf("write session ref on turn-end: %w", err)
117				}
118			}
119			model := raw.Model
120			if model == "" {
121				model = latestModelFromSessionRef(sessionRef)
122			}
