295	func safeFilename(name string) string {
296		name = strings.TrimSpace(name)
297		if name == "" {
298			return stubSessionID
299		}
300		var b strings.Builder
301		for _, r := range name {
302			switch {
303			case r == '-' || r == '_' || r == '.':
304				b.WriteRune(r)
305			case r >= '0' && r <= '9':
306				b.WriteRune(r)
307			case r >= 'a' && r <= 'z':
308				b.WriteRune(r)
309			case r >= 'A' && r <= 'Z':
310				b.WriteRune(r)
311			default:
312				if unicode.IsLetter(r) || unicode.IsNumber(r) {
313					b.WriteRune(r)
314				} else {
315					b.WriteByte('_')
316				}
317			}
318		}
319		out := strings.Trim(b.String(), "._")
320		if out == "" {
321			return stubSessionID
322		}
323		return out
324	}
