  1	package grok
  2	
  3	import (
  4		"fmt"
  5		"os"
  6		"path/filepath"
  7		"strings"
  8	
  9		"github.com/entireio/external-agents/agents/entire-agent-grok/internal/protocol"
 10	)
 11	
 12	const nativeTranscriptFile = "chat_history.jsonl"
 13	
 14	// maxEncodedCWDLen is the point at which Grok stops using the encoded working
 15	// directory as the session group name and switches to a slug plus a hash,
 16	// recording the original path in a .cwd file inside the group instead.
 17	const maxEncodedCWDLen = 255
 18	
 19	// cwdMarkerFile names the file Grok writes inside a hashed session group to
 20	// record which working directory it belongs to.
 21	const cwdMarkerFile = ".cwd"
 22	
 23	func grokHome() string {
 24		if home := strings.TrimSpace(os.Getenv("GROK_HOME")); home != "" {
 25			return home
 26		}
 27		userHome, err := os.UserHomeDir()
 28		if err != nil {
 29			return ""
 30		}
 31		return filepath.Join(userHome, ".grok")
 32	}
 33	
 34	// resolveRepoPath canonicalizes a repo path the way Grok sees it. macOS temp
 35	// directories live under /var, a symlink to /private/var, so the path must be
 36	// resolved or the encoded group name will not match Grok's.
 37	func resolveRepoPath(repoPath string) string {
 38		repoPath = strings.TrimSpace(repoPath)
 39		if repoPath == "" {
 40			repoPath = protocol.RepoRoot()
 41		}
 42		if resolved, err := filepath.EvalSymlinks(repoPath); err == nil {
 43			repoPath = resolved
 44		}
 45		return filepath.Clean(repoPath)
 46	}
 47	
 48	// encodeRepoCWD percent-encodes a working directory into Grok's session group
 49	// name.
 50	//
 51	// Grok URL-encodes every byte outside the RFC 3986 unreserved set
 52	// (ALPHA / DIGIT / "-" / "." / "_" / "~") using uppercase hex, so "/" becomes
 53	// %2F, a space becomes %20 and "é" becomes %C3%A9. Encoding only "/" — as this
 54	// did — silently misses any repo path containing a space, an accent, or
 55	// punctuation such as !()'*+@&=,;:$, and Entire then looks for a session
 56	// directory that does not exist.
 57	//
 58	// Note this is stricter than Go's url.PathEscape, which leaves the sub-delims
 59	// $&+,;=:@ unescaped in a path segment. Grok escapes those.
 60	func encodeRepoCWD(repoPath string) string {
 61		return percentEncodeCWD(resolveRepoPath(repoPath))
 62	}
 63	
 64	func percentEncodeCWD(path string) string {
 65		var encoded strings.Builder
 66		encoded.Grow(len(path))
 67		for i := range len(path) {
 68			if c := path[i]; isUnreservedCWDByte(c) {
 69				encoded.WriteByte(c)
 70				continue
 71			}
 72			fmt.Fprintf(&encoded, "%%%02X", path[i])
 73		}
 74		return encoded.String()
 75	}
 76	
 77	func isUnreservedCWDByte(c byte) bool {
 78		switch {
 79		case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c >= '0' && c <= '9':
 80			return true
 81		case c == '-', c == '.', c == '_', c == '~':
 82			return true
 83		default:
 84			return false
 85		}
 86	}
 87	
 88	// nativeSessionDir returns the Grok session group directory for a repo.
 89	//
 90	// Below the length limit the group is named after the encoded path. Above it,
 91	// Grok uses "<last-path-segment>-<hash>", and the hash is not something we can
 92	// reproduce, so the group is located by reading the .cwd marker Grok leaves in
 93	// each hashed group.
 94	//
 95	// If no marker matches — a repo Grok has never opened — the encoded name is
 96	// returned so discovery has something to report, but it is over the limit and
 97	// cannot be created: a write through it fails with ENAMETOOLONG, which
 98	// WriteSession reports with the offending directory named.
 99	func nativeSessionDir(repoPath string) string {
100		resolved := resolveRepoPath(repoPath)
101		root := filepath.Join(grokHome(), "sessions")
102		encoded := percentEncodeCWD(resolved)
103		if len(encoded) <= maxEncodedCWDLen {
104			return filepath.Join(root, encoded)
105		}
106		if hashed := findHashedSessionDir(root, resolved); hashed != "" {
107			return hashed
108		}
109		return filepath.Join(root, encoded)
110	}
111	
112	// findHashedSessionDir scans session groups for the .cwd marker naming repoPath.
113	func findHashedSessionDir(root, repoPath string) string {
114		entries, err := os.ReadDir(root)
115		if err != nil {
116			return ""
117		}
118		for _, entry := range entries {
119			if !entry.IsDir() {
120				continue
121			}
122			marker, err := os.ReadFile(filepath.Join(root, entry.Name(), cwdMarkerFile))
123			if err != nil {
124				continue
125			}
126			if strings.TrimSpace(string(marker)) == repoPath {
127				return filepath.Join(root, entry.Name())
128			}
129		}
130		return ""
131	}
132	
133	func nativeTranscriptPath(repoPath, sessionID string) string {
134		if strings.TrimSpace(sessionID) == "" {
135			sessionID = stubSessionID
136		}
137		return filepath.Join(nativeSessionDir(repoPath), sessionID, nativeTranscriptFile)
138	}
139	
140	func (a *Agent) resolveSessionRef(sessionID, repoPath string) string {
141		if strings.TrimSpace(repoPath) == "" {
142			repoPath = protocol.RepoRoot()
143		}
144		return nativeTranscriptPath(repoPath, sessionID)
145	}

