package kilo

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
)

func TestResolveSessionFile(t *testing.T) {
	sessionDir := filepath.Join(t.TempDir(), ".entire", "tmp")
	want := filepath.Join(sessionDir, "abc123.json")

	if got := New().ResolveSessionFile(sessionDir, "abc123"); got != want {
		t.Fatalf("ResolveSessionFile() = %q, want %q", got, want)
	}
}

func TestResolveSessionFileContainsHostileIDs(t *testing.T) {
	sessionDir := filepath.Join(t.TempDir(), ".entire", "tmp")
	for _, id := range []string{
		"../etc/passwd",
		"..\\etc\\passwd",
		"subdir/../../etc/passwd",
		"/etc/passwd",
		"id\x00.json",
	} {
		t.Run(id, func(t *testing.T) {
			got := New().ResolveSessionFile(sessionDir, id)
			if filepath.Dir(got) != sessionDir {
				t.Fatalf("ResolveSessionFile(%q) = %q, want a file directly in %q", id, got, sessionDir)
			}
			if filepath.Ext(got) != ".json" {
				t.Fatalf("ResolveSessionFile(%q) = %q, want .json extension", id, got)
			}
		})
	}
}

func TestResolveSessionFileWriteSessionCannotWriteOutside(t *testing.T) {
	root := t.TempDir()
	sessionDir := filepath.Join(root, "sessions")
	outsidePath := filepath.Join(root, "outside", "pwned.json")
	if err := os.MkdirAll(filepath.Dir(outsidePath), 0o700); err != nil {
		t.Fatal(err)
	}
	const sentinel = "outside sentinel"
	if err := os.WriteFile(outsidePath, []byte(sentinel), 0o600); err != nil {
		t.Fatal(err)
	}

	agent := New()
	sessionRef := agent.ResolveSessionFile(sessionDir, "../outside/pwned")
	const transcript = "attacker-influenced transcript"
	if err := agent.WriteSession(protocol.AgentSessionJSON{
		SessionRef: sessionRef,
		NativeData: []byte(transcript),
	}); err != nil {
		t.Fatalf("WriteSession(%q): %v", sessionRef, err)
	}

	outsideData, err := os.ReadFile(outsidePath)
	if err != nil {
		t.Fatal(err)
	}
	if string(outsideData) != sentinel {
		t.Fatalf("outside file was overwritten through resolver-produced session ref: got %q", outsideData)
	}
	written, err := os.ReadFile(sessionRef)
	if err != nil {
		t.Fatalf("read contained transcript: %v", err)
	}
	if string(written) != transcript {
		t.Fatalf("contained transcript = %q, want %q", written, transcript)
	}
}
package grok

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/external-agents/agents/entire-agent-grok/internal/protocol"
)

func TestEncodeRepoCWD(t *testing.T) {
	repo := "/Users/test/project"
	encoded := encodeRepoCWD(repo)
	if encoded != "%2FUsers%2Ftest%2Fproject" {
		t.Fatalf("unexpected encoded cwd: %q", encoded)
	}
}

func TestNativeTranscriptPath(t *testing.T) {
	t.Setenv("GROK_HOME", t.TempDir())
	repo := "/Users/test/project"
	path := nativeTranscriptPath(repo, "session-123")
	wantSuffix := filepath.Join("sessions", "%2FUsers%2Ftest%2Fproject", "session-123", "chat_history.jsonl")
	if !strings.HasSuffix(path, wantSuffix) {
		t.Fatalf("unexpected transcript path %q", path)
	}
}

func TestSessionFileResolversContainUnsafeSessionIDs(t *testing.T) {
	grokHome := t.TempDir()
	t.Setenv("GROK_HOME", grokHome)
	repo := t.TempDir()
	sessionDir := filepath.Join(t.TempDir(), "sessions")
	agent := New()

	for _, sessionID := range []string{
		"../../../../tmp/pwned",
		`..\..\tmp\pwned`,
		"nested/session",
	} {
		t.Run(sessionID, func(t *testing.T) {
			safeID := safeFilename(sessionID)

			publicPath := agent.ResolveSessionFile(sessionDir, sessionID)
			wantPublicPath := filepath.Join(sessionDir, safeID, nativeTranscriptFile)
			if publicPath != wantPublicPath {
				t.Fatalf("ResolveSessionFile() = %q, want %q", publicPath, wantPublicPath)
			}
			assertPathWithin(t, sessionDir, publicPath)

			nativeDir := nativeSessionDir(repo)
			wantNativePath := filepath.Join(nativeDir, safeID, nativeTranscriptFile)
			if got := nativeTranscriptPath(repo, sessionID); got != wantNativePath {
				t.Fatalf("nativeTranscriptPath() = %q, want %q", got, wantNativePath)
			}
			if got := agent.resolveSessionRef(sessionID, repo); got != wantNativePath {
				t.Fatalf("resolveSessionRef() = %q, want %q", got, wantNativePath)
			}
			assertPathWithin(t, nativeDir, wantNativePath)
		})
	}
}

func TestParseHookContainsUnsafeSessionIDInSessionRef(t *testing.T) {
	t.Setenv("GROK_HOME", t.TempDir())
	repo := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repo)
	agent := New()
	sessionID := "../../outside"

	payload, err := json.Marshal(map[string]string{
		"session_id": sessionID,
		"cwd":        repo,
	})
	if err != nil {
		t.Fatal(err)
	}
	event, err := agent.ParseHook(HookNameSessionStart, payload)
	if err != nil {
		t.Fatalf("ParseHook(): %v", err)
	}
	if event == nil {
		t.Fatal("ParseHook() returned no event")
	}

	sessionDir := nativeSessionDir(repo)
	want := filepath.Join(sessionDir, safeFilename(sessionID), nativeTranscriptFile)
	if event.SessionRef != want {
		t.Fatalf("SessionRef = %q, want %q", event.SessionRef, want)
	}
	assertPathWithin(t, sessionDir, event.SessionRef)
}

func TestWriteSessionWithResolvedUnsafeIDStaysWithinSessionDir(t *testing.T) {
	t.Setenv("GROK_HOME", t.TempDir())
	root := t.TempDir()
	sessionDir := filepath.Join(root, "sessions")
	outsidePath := filepath.Join(root, "outside", nativeTranscriptFile)
	if err := os.MkdirAll(filepath.Dir(outsidePath), 0o700); err != nil {
		t.Fatal(err)
	}
	const sentinel = "do not overwrite"
	if err := os.WriteFile(outsidePath, []byte(sentinel), 0o600); err != nil {
		t.Fatal(err)
	}

	agent := New()
	sessionID := "../outside"
	sessionRef := agent.ResolveSessionFile(sessionDir, sessionID)
	nativeData := []byte("{\"type\":\"user\",\"content\":\"restored\"}\n")
	if err := agent.WriteSession(protocol.AgentSessionJSON{
		SessionID:  sessionID,
		RepoPath:   root,
		SessionRef: sessionRef,
		NativeData: nativeData,
	}); err != nil {
		t.Fatalf("WriteSession(): %v", err)
	}

	outsideData, err := os.ReadFile(outsidePath)
	if err != nil {
		t.Fatal(err)
	}
	if string(outsideData) != sentinel {
		t.Fatalf("outside transcript was overwritten with %q", outsideData)
	}
	assertPathWithin(t, sessionDir, sessionRef)
	written, err := os.ReadFile(sessionRef)
	if err != nil {
		t.Fatalf("read contained transcript: %v", err)
	}
	if string(written) != string(nativeData) {
		t.Fatalf("contained transcript = %q, want %q", written, nativeData)
	}
}

func assertPathWithin(t *testing.T, base, path string) {
	t.Helper()
	rel, err := filepath.Rel(base, path)
	if err != nil {
		t.Fatalf("filepath.Rel(%q, %q): %v", base, path, err)
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		t.Fatalf("path %q escapes base %q (relative path %q)", path, base, rel)
	}
}

