// safeFilename reduces an untrusted session ID to one path component.
// Transcript directories and marker files must use the same mapping.
func safeFilename(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return stubSessionID
	}
	var b strings.Builder
	for _, r := range name {
		switch {
		case r == '-' || r == '_' || r == '.':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= 'A' && r <= 'Z':
			b.WriteRune(r)
		default:
			if unicode.IsLetter(r) || unicode.IsNumber(r) {
				b.WriteRune(r)
			} else {
				b.WriteByte('_')
			}
		}
	}
	out := strings.Trim(b.String(), "._")
	if out == "" {
		return stubSessionID
	}
	return out
}

