package kilo

import (
	"path/filepath"
	"regexp"

	"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
)

func (a *Agent) GetSessionDir(repoPath string) (string, error) {
	return protocol.DefaultSessionDir(repoPath), nil
}

var sessionIDPathSanitizer = regexp.MustCompile(`[^A-Za-z0-9_.-]+`)

// safeSessionID replaces runs outside A-Za-z0-9_.- with an underscore and
// maps an empty ID to "unknown". Dots are safe here because callers append a
// filename extension, so even "." and ".." cannot become path segments.
func safeSessionID(sessionID string) string {
	if sessionID == "" {
		return "unknown"
	}
	return sessionIDPathSanitizer.ReplaceAllString(sessionID, "_")
}

func (a *Agent) ResolveSessionFile(sessionDir, sessionID string) string {
	return filepath.Join(sessionDir, safeSessionID(sessionID)+".json")
}
