func TestSessionFileResolversContainUnsafeSessionIDs(t *testing.T) {
	grokHome := t.TempDir()
	t.Setenv("GROK_HOME", grokHome)
	repo := t.TempDir()
	sessionDir := filepath.Join(t.TempDir(), "sessions")
	agent := New()

	tests := []struct {
		name      string
		sessionID string
		safeID    string
	}{
		{name: "benign", sessionID: "session-123", safeID: "session-123"},
		{name: "slash traversal", sessionID: "../../../../tmp/pwned", safeID: "tmp_pwned"},
		{name: "backslash traversal", sessionID: `..\..\tmp\pwned`, safeID: "tmp_pwned"},
		{name: "nested path", sessionID: "nested/session", safeID: "nested_session"},
		{name: "trailing whitespace", sessionID: ".. ", safeID: stubSessionID},
		{name: "leading whitespace", sessionID: " ..", safeID: stubSessionID},
		{name: "surrounding whitespace", sessionID: " .. ", safeID: stubSessionID},
		{name: "windows drive relative", sessionID: "C:outside", safeID: "C_outside"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := safeFilename(tt.sessionID); got != tt.safeID {
				t.Fatalf("safeFilename() = %q, want %q", got, tt.safeID)
			}

			publicPath := agent.ResolveSessionFile(sessionDir, tt.sessionID)
			wantPublicPath := filepath.Join(sessionDir, tt.safeID, nativeTranscriptFile)
			if publicPath != wantPublicPath {
				t.Fatalf("ResolveSessionFile() = %q, want %q", publicPath, wantPublicPath)
			}
			assertPathWithin(t, sessionDir, publicPath)

			nativeDir := nativeSessionDir(repo)
			wantNativePath := filepath.Join(nativeDir, tt.safeID, nativeTranscriptFile)
			if got := nativeTranscriptPath(repo, tt.sessionID); got != wantNativePath {
				t.Fatalf("nativeTranscriptPath() = %q, want %q", got, wantNativePath)
			}
			if got := agent.resolveSessionRef(tt.sessionID, repo); got != wantNativePath {
				t.Fatalf("resolveSessionRef() = %q, want %q", got, wantNativePath)
			}
			assertPathWithin(t, nativeDir, wantNativePath)
		})
	}
}

