func safeSessionFileComponent(sessionID string) string {
	var name strings.Builder
	for _, r := range sessionID {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == '-' || r == '_' {
			name.WriteRune(r)
		} else {
			name.WriteByte('-')
		}
		if name.Len() >= 80 {
			break
		}
	}
	trimmed := strings.Trim(name.String(), "-")
	if trimmed == "" {
		return "session"
	}
	return trimmed
