// safeFilename reduces an untrusted session ID to one path component. Safe IDs
// are unchanged; transformed and fallback IDs include a hash of the original.
// Transcript directories and marker files must use the same mapping.
func safeFilename(name string) string {
	original := name
	name = strings.TrimSpace(name)
	var b strings.Builder
	for _, r := range name {
		switch {
		case r == '-' || r == '_' || r == '.':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= 'A' && r <= 'Z':
			b.WriteRune(r)
		default:
			if unicode.IsLetter(r) || unicode.IsNumber(r) {
				b.WriteRune(r)
			} else {
				b.WriteByte('_')
			}
		}
	}
	out := strings.Trim(b.String(), "._")
	if out == "" {
		out = stubSessionID
	}
	if out == original {
		return out
	}
	sum := sha256.Sum256([]byte(original))
	return fmt.Sprintf("%s-%x", out, sum[:8])
}

